WITH x11 AS (SELECT x8.v1884, x8.v1884, x8.v1884, GROUPING(x8.v1884) AS x15 FROM x16 GROUP BY x8.v1884, x8.v1884, x8.v1884 WITH ROLLUP) SELECT x8.v1884, x8.v1884, CONCAT_WS(REPEAT(CONCAT(x8.v1884 COLLATE utf8mb4_roman_ci), -1330441018), CONCAT_WS('', CONCAT(HEX(STRCMP('9', x8.v1884))), (x8.v1884 - INTERVAL '-1941528800' DAY_MINUTE))) AS x4, x8.v1884 FROM v1883 AS x8 WHERE x8.v1884 <> 'AME'